"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[21513],{72704:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>r,contentTitle:()=>s,default:()=>u,frontMatter:()=>a,metadata:()=>o,toc:()=>d});var h=n(31085),i=n(71184);const a={sidebar_position:19,slug:"/bible/Judges/Judges_19",title:"Judges 19",hide_table_of_contents:!0},s="Judges",o={id:"bible/Judges/Judges 19",title:"Judges 19",description:"Chapter 19",source:"@site/docs/bible/Judges/Judges 19.md",sourceDirName:"bible/Judges",slug:"/bible/Judges/Judges_19",permalink:"/docs/bible/Judges/Judges_19",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/Judges/Judges 19.md",tags:[],version:"current",sidebarPosition:19,frontMatter:{sidebar_position:19,slug:"/bible/Judges/Judges_19",title:"Judges 19",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Judges 18",permalink:"/docs/bible/Judges/Judges_18"},next:{title:"Judges 20",permalink:"/docs/bible/Judges/Judges_20"}},r={},d=[{value:"Chapter 19",id:"chapter-19",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,i.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(t.h1,{id:"judges",children:"Judges"}),"\n",(0,h.jsx)(t.h2,{id:"chapter-19",children:"Chapter 19"}),"\n",(0,h.jsx)(t.p,{children:"A Levite bringing home his wife, is lodged by an old man at Gabaa in the tribe of Benjamin.  His wife is there abused by wicked men, and in the morning found dead.  Her husband cutteth her body in pieces, and sendeth to every tribe of Israel, requiring them to revenge the wicked fact."}),"\n",(0,h.jsx)(n,{verse:1,children:"There was a certain Levite, who dwelt on the side of mount Ephraim, who took a wife of Bethlehem Juda:"}),"\n",(0,h.jsx)(n,{verse:2,children:"And she left him, and returned to her father's house in Bethlehem, and abode with him four months."}),"\n",(0,h.jsx)(n,{verse:3,children:"And her husband followed her, willing to be reconciled with her, and to speak kindly to her, and to bring her back with him, having with him a servant and two asses: and she received him, and brought him into her father's house. And when his father in law had heard this, and had seen him, he met him with joy,"}),"\n",(0,h.jsx)(n,{verse:4,children:"And embraced the man. And the son in law tarried in the house of his father in law three days, eating with him and drinking familiarly."}),"\n",(0,h.jsx)(n,{verse:5,children:"But on the fourth day, arising early in the morning, he desired to depart. But his father in law kept him, and said to him: Taste first a little bread, and strengthen thy stomach, and so thou shalt depart."}),"\n",(0,h.jsx)(n,{verse:6,children:"And they sat down together, and ate and drank. And the father of the young woman said to his son in law: I beseech thee to stay here to day, and let us make merry together."}),"\n",(0,h.jsx)(n,{verse:7,children:"But he rising up, began to be for departing. And nevertheless his father in law earnestly pressed him, and made him stay with him."}),"\n",(0,h.jsx)(n,{verse:8,children:"But when morning was come, the Levite prepared to go on his journey. And his father in law said to him again: I beseech thee to take a little meat, and strengthening thyself, till the day be farther advanced, afterwards thou mayest depart. And they ate together."}),"\n",(0,h.jsx)(n,{verse:9,children:"And the young man arose to set forward with his wife and servant. And his father in law spoke to him again: Consider that the day is declining, and draweth toward evening: tarry with me to day also, and spend the day in mirth, and to morrow thou shalt depart, that thou mayest go into thy house."}),"\n",(0,h.jsx)(n,{verse:10,children:"His son in law would not consent to his words: but forthwith went forward, and came over against Jebus, which by another name is called Jerusalem, leading with him two asses loaden, and his concubine. Concubine. She was his lawful wife, but even lawful wives are frequently in scripture called concubines. See above, chap. 8. ver."}),"\n",(0,h.jsx)(t.admonition,{type:"note",children:(0,h.jsx)(t.p,{children:"Note 1: 31.-ver. 16. Jemini...That is, Benjamin."})}),"\n",(0,h.jsx)(n,{verse:11,children:"And now they were come near Jebus, and the day was far spent: and the servant said to his master: Come, I beseech thee, let us turn into the city of the Jebusites, and lodge there."}),"\n",(0,h.jsx)(n,{verse:12,children:"His master answered him: I will not go into the town of another nation, who are not of the children of Israel, but I will pass over to Gabaa:"}),"\n",(0,h.jsx)(n,{verse:13,children:"And when I shall come thither, we will lodge there, or at least in the city of Rama."}),"\n",(0,h.jsx)(n,{verse:14,children:"So they passed by Jebus, and went on their journey, and the sun went down upon them when they were by Gabaa, which is in the tribe of Benjamin:"}),"\n",(0,h.jsx)(n,{verse:15,children:"And they turned into it to lodge there. And when they were come in, they sat in the street of the city, for no man would receive them to lodge."}),"\n",(0,h.jsx)(n,{verse:16,children:"And behold they saw an old man, returning out of the field and from his work in the evening, and he also was of mount Ephraim, and dwelt as a stranger in Gabaa; but the men of that country were the children of Jemini."}),"\n",(0,h.jsx)(n,{verse:17,children:"And the old man lifting up his eyes, saw the man sitting with his bundles in the street of the city, and said to him: Whence comest thou? and whither goest thou?"}),"\n",(0,h.jsx)(n,{verse:18,children:"He answered him: We came out from Bethlehem Juda, and we are going to our home, which is on the side of mount Ephraim, from whence we went to Bethlehem: and now we go to the house of God, and none will receive us under his roof:"}),"\n",(0,h.jsx)(n,{verse:19,children:"We have straw and hay for provender of the asses, and bread and wine for the use of myself and of thy handmaid, and of the servant that is with me: we want nothing but lodging."}),"\n",(0,h.jsx)(n,{verse:20,children:"And the old man answered him: Peace be with thee: I will furnish all things that are necessary: only I beseech thee, stay not in the street."}),"\n",(0,h.jsx)(n,{verse:21,children:"And he brought him into his house, and gave provender to his asses: and after they had washed their feet, he entertained them with a feast."}),"\n",(0,h.jsx)(n,{verse:22,children:"While they were making merry, and refreshing their bodies with meat and drink, after the labour of the journey, the men of that city, sons of Belial (that is, without yoke), came and beset the old man's house, and began to knock at the door, calling to the master of the house, and saying: Bring forth the man that came into thy house, that we may abuse him:"}),"\n",(0,h.jsx)(n,{verse:23,children:"And the old man went out to them, and said: Do not so, my brethren, do not so wickedly: because this man is come into my lodging, and cease I pray you from this folly."}),"\n",(0,h.jsx)(n,{verse:24,children:"I have a maiden daughter, and this man hath a concubine, I will bring them out to you, and you may humble them, and satisfy your lust: only, I beseech you, commit not this crime against nature on the man."}),"\n",(0,h.jsx)(n,{verse:25,children:"They would not be satisfied with his words; which the man seeing, brought out his concubine to them, and abandoned her to their wickedness: and when they had abused her all the night, they let her go in the morning."}),"\n",(0,h.jsx)(n,{verse:26,children:"But the woman, at the dawning of the day, came to the door of the house, where her lord lodged, and there fell down."}),"\n",(0,h.jsx)(n,{verse:27,children:"And in the morning the man arose, and opened the door, that he might end the journey he had begun: and behold his concubine lay before the door with her hands spread on the threshold."}),"\n",(0,h.jsx)(n,{verse:28,children:"He thinking she was taking her rest, said to her: Arise, and let us be going. But as she made no answer, perceiving she was dead, he took her up, and laid her upon his ass, and returned to his house."}),"\n",(0,h.jsx)(n,{verse:29,children:"And when he was come home, he took a sword, and divided the dead body of his wife with her bones into twelve parts, and sent the pieces into all the borders of Israel."}),"\n",(0,h.jsx)(n,{verse:30,children:"And when every one had seen this, they all cried out: There was never such a thing done in Israel, from the day that our fathers came up out of Egypt, until this day: give sentence, and decree in common what ought to be done."})]})}function u(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,h.jsx)(t,{...e,children:(0,h.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>o});var h=n(14041);const i={},a=h.createContext(i);function s(e){const t=h.useContext(a);return h.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),h.createElement(a.Provider,{value:t},e.children)}}}]);